Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.
(* [comment removed for export] *)
Local Ltac norm_regset ::=
  repeat match goal with
  | |- context [@bvmap_set 5 word ?r ?v ?R] =>
      lazymatch R with TNode _ _ _ => idtac | TEmpty => idtac end;
      let p := eval vm_compute in (bv_key r) in
      change (@bvmap_set 5 word r v R) with (tset p v R);
      cbv beta iota delta [tset mkR]
  end.

(* [comment removed for export] *)
Definition arange (a n : Z) : Prop := 0 < a /\ a + n <= 2^47 /\ (a + n <= 0x7fff7000 \/ 0x10007fff8000 <= a) /\ (a + n <= 0x10000 \/ 0x66f000 <= a).

Definition hacc (m : mem) (a n : Z) : Prop := acc asegs m a n.
Ltac hide_accs := repeat match goal with H : acc asegs ?m ?a ?n |- _ => change (hacc m a n) in H end.
Ltac show_acc H := unfold hacc in H.
Definition hfact (P : Prop) : Prop := P.
Ltac hide_fact H := lazymatch type of H with ?t => change (hfact t) in H end.

(* [comment removed for export] *)
Definition acc_regs (F : bvmap 5 word) (s n : Z) : Prop :=
  reg_get F (Z_to_bv 5 13) = nan_box (Z_to_bv 32 s) /\ reg_get F (Z_to_bv 5 14) = nan_box (Z_to_bv 32 n).

(* [comment removed for export] *)
Record bgm : Type := mk_bgm {
  m_D : Z; m_N : Z;              (* [comment removed for export] *)
  m_KELP : Z; m_keli : Z; m_kdata : Z; m_kk : Z; m_sy : Z; m_KR : Z; m_sx : Z;
  m_RKP : Z; m_rdata : Z; m_RR : Z;
  m_cx : Z }.
Definition bgm_ok (p : bgm) : Prop :=
  arange (m_D p) (m_N p) /\ m_D p mod 4 = 0 /\ m_N p mod 4 = 0
  /\ arange (m_KELP p) 8 /\ m_KELP p mod 8 = 0
  /\ arange (m_keli p) 24 /\ m_keli p mod 8 = 0
  /\ arange (m_kdata p) (8 * m_sy p) /\ m_kdata p mod 8 = 0 /\ 0 <= m_kk p < m_sy p /\ 0 < m_sy p <= 2048
  /\ arange (m_KR p) (4 * m_sx p) /\ m_KR p mod 4 = 0 /\ 0 < m_sx p <= 2048 /\ 0 <= m_cx p < m_sx p
  /\ arange (m_RKP p) 8 /\ m_RKP p mod 8 = 0 /\ arange (m_rdata p) 8 /\ m_rdata p mod 8 = 0 /\ arange (m_RR p) 1024 /\ m_RR p mod 4 = 0.
Definition bgm_ro (p : bgm) (ks rs : Z -> Z) (m : mem) : Prop :=
  wr_at asegs m (m_D p) (m_N p) /\ acc asegs m (m_D p) (m_N p)
  /\ rw_cells asegs m (m_KELP p) [C8 (Z_to_bv 64 (m_keli p))] /\ acc asegs m (m_KELP p) 8
  /\ rw_cells asegs m (m_keli p + 16) [C8 (Z_to_bv 64 (m_kdata p))] /\ acc asegs m (m_keli p) 24
  /\ rw_cells asegs m (m_kdata p + 8 * m_kk p) [C8 (Z_to_bv 64 (m_KR p))] /\ acc asegs m (m_kdata p) (8 * m_sy p)
  /\ (forall q, 0 <= q < m_sx p -> rw_cells asegs m (m_KR p + 4 * q) [C4 (Z_to_bv 64 (ks q))] /\ FB fmt_single 1 (ks q)) /\ acc asegs m (m_KR p) (4 * m_sx p)
  /\ rw_cells asegs m (m_RKP p) [C8 (Z_to_bv 64 (m_rdata p))] /\ acc asegs m (m_RKP p) 8
  /\ rw_cells asegs m (m_rdata p) [C8 (Z_to_bv 64 (m_RR p))] /\ acc asegs m (m_rdata p) 8
  /\ (forall q, 0 <= q < 256 -> rw_cells asegs m (m_RR p + 4 * q) [C4 (Z_to_bv 64 (rs q))] /\ FB fmt_single 1 (rs q)) /\ acc asegs m (m_RR p) 1024
  /\ rs 0 = p_one_s.

(* [comment removed for export] *)
Lemma bge_tap : forall (G : bvmap 5 word) (s0 n0 kt : Z) (cb cb2 : bool) (sp rg bv : Z),
  acc_regs G s0 n0 -> ge_avg kt cb s0 n0 -> 0 <= kt -> kt + 1 <= 2048 -> FB fmt_single 1 sp -> FB fmt_single 1 rg -> 0 <= bv <= 255 ->
  (cb2 = true -> cb = true \/ (sp = p_one_s /\ rg = p_one_s)) ->
  let SPw := nan_box (bv_extract 0 32 (le_bytes_to_word (le4 (Z_to_bv 64 sp)))) in
  let RGw := nan_box (bv_extract 0 32 (le_bytes_to_word (le4 (Z_to_bv 64 rg)))) in
  let KW := fmul_s RNE SPw RGw in
  exists s1 n1 : Z, fma_s F_MADD RNE (fcvt_s_wu RNE (Z_to_bv 64 bv)) KW (reg_get G (Z_to_bv 5 13)) = nan_box (Z_to_bv 32 s1)
    /\ fadd_s RNE (reg_get G (Z_to_bv 5 14)) KW = nan_box (Z_to_bv 32 n1) /\ ge_avg (kt + 1) cb2 s1 n1.
Proof.
