(* [comment removed for export] *)
Ltac acc_regs_tac := split; (repeat (rewrite freg_get_other by reflexivity)); rewrite freg_get_same by reflexivity; reflexivity.

(* [comment removed for export] *)
Definition f15_kept (F F' : bvmap 5 word) : Prop := reg_get F' (Z_to_bv 5 15) = reg_get F (Z_to_bv 5 15).
Ltac f15_tac := unfold f15_kept; (repeat (rewrite freg_get_other by reflexivity)); reflexivity.

(* [comment removed for export] *)
Definition bge_m_exit (p : bgm) (K : Z) (cb ctr : bool) (sp gp tp t2 s0 s1 a1 a4 a5 s2 s4 s6 s7 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (m : mem)
  : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' a0' a2' a3' s3' : word) (F' : bvmap 5 word) (fc' : bv 32) (s' n' : Z) (cb' : bool),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2 s0 s1 a0' a1 a2' a3' a4 a5 (Z_to_bv 64 1) (Z_to_bv 64 3) s2 s3' s4 (Z_to_bv 64 (4 * m_sx p)) s6 s7
                  (Z_to_bv 64 (4 * m_sx p)) s9 s10 s11 t3 t4 t5 t6)
             F' (Z_to_bv 64 0xd1938) fc' None m (seg_rom asegs)
    /\ fs_agree F F' /\ f15_kept F F' /\ frm0 fc' /\ acc_regs F' s' n' /\ ge_avg K cb' s' n' /\ (cb = true -> cb' = true) /\ (ctr = true -> cb' = true).

(* [comment removed for export] *)
Lemma bge_m_loop : forall (k : nat) (p : bgm) (ks rs : Z -> Z) (mm L j c kt K : Z) (cb ctr : bool)
    (sp gp tp t0 t1 s0 s1 a0 a2 a3 a4 a5 s2 s3 s4 s6 s10 s11 t3 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (s n : Z),
  Z.of_nat k = m_sx p - mm -> 0 <= mm -> (1 <= k)%nat -> bgm_ok p -> bgm_ro p ks rs m -> mem_inv asegs m -> frm0 fc ->
  0 <= c < 256 -> 0 <= j <= 20000 -> 0 <= L -> m_D p <= L + j -> L + j + m_sx p <= m_D p + m_N p ->
  acc_regs F s n -> ge_avg kt cb s n -> 0 <= kt -> K = kt + (m_sx p - mm) -> K <= 2048 ->
  (ctr = true -> ks (m_cx p) = p_one_s /\ exists cbyte : byte, rw_cells asegs m (Z.lxor (L + j + m_cx p) 3) [CB 1 [cbyte]] /\ c = bv_unsigned cbyte) ->
  (ctr = true -> cb = true \/ mm <= m_cx p) ->
  evt asegs (bge_m_exit p K cb ctr sp gp tp (Z_to_bv 64 j) s0 s1 (Z_to_bv 64 (m_RKP p)) a4 a5 s2 s4 s6 (Z_to_bv 64 (m_KELP p)) (Z_to_bv 64 2147450880) s10 s11 t3
               (Z_to_bv 64 (8 * m_kk p)) (Z_to_bv 64 c) (Z_to_bv 64 L) F m)
    (MS (mkR (Z_to_bv 64 mm) sp gp tp t0 t1 (Z_to_bv 64 j) s0 s1 a0 (Z_to_bv 64 (m_RKP p)) a2 a3 a4 a5 (Z_to_bv 64 1) (Z_to_bv 64 3)
             s2 s3 s4 (Z_to_bv 64 (4 * m_sx p)) s6 (Z_to_bv 64 (m_KELP p)) (Z_to_bv 64 (4 * mm)) (Z_to_bv 64 2147450880) s10 s11
             t3 (Z_to_bv 64 (8 * m_kk p)) (Z_to_bv 64 c) (Z_to_bv 64 L))
