  k_RKP : Z; k_rdata : Z; k_RR : Z }.
Definition bgk_ok (q : bgk) : Prop :=
  arange (k_D q) (k_N q) /\ k_D q mod 4 = 0 /\ k_N q = 4 * (k_wpls q * k_ht q) /\ 0 < k_wpls q /\ k_wpls q * k_ht q <= 2^26
  /\ 0 < k_w q <= 20000 /\ 0 < k_h q <= 20000 /\ k_w q + k_sx q <= 4 * k_wpls q /\ k_h q + k_sy q <= k_ht q
  /\ arange (k_KELP q) 8 /\ k_KELP q mod 8 = 0 /\ arange (k_keli q) 24 /\ k_keli q mod 8 = 0
  /\ arange (k_kdata q) (8 * k_sy q) /\ k_kdata q mod 8 = 0 /\ Z.of_nat (length (k_rows q)) = k_sy q
  /\ 0 < k_sy q /\ 0 < k_sx q /\ k_sy q * k_sx q <= 2048 /\ 0 <= k_cy q < k_sy q /\ 0 <= k_cx q < k_sx q
  /\ Forall (fun r => arange r (4 * k_sx q) /\ r mod 4 = 0) (k_rows q)
  /\ arange (k_SXP q) 4 /\ k_SXP q mod 4 = 0
  /\ arange (k_RKP q) 8 /\ k_RKP q mod 8 = 0 /\ arange (k_rdata q) 8 /\ k_rdata q mod 8 = 0 /\ arange (k_RR q) 1024 /\ k_RR q mod 4 = 0.
Definition bgk_ro (q : bgk) (ksf : Z -> Z -> Z) (rs : Z -> Z) (m : mem) : Prop :=
  wr_at asegs m (k_D q) (k_N q) /\ acc asegs m (k_D q) (k_N q)
  /\ rw_cells asegs m (k_KELP q) [C8 (Z_to_bv 64 (k_keli q))] /\ acc asegs m (k_KELP q) 8
  /\ rw_cells asegs m (k_keli q + 16) [C8 (Z_to_bv 64 (k_kdata q))] /\ acc asegs m (k_keli q) 24
  /\ u64arr asegs m (k_kdata q) (map (Z_to_bv 64) (k_rows q)) /\ acc asegs m (k_kdata q) (8 * k_sy q)
  /\ (forall kk r qq, nth_error (k_rows q) (Z.to_nat kk) = Some r -> 0 <= kk -> 0 <= qq < k_sx q ->
        rw_cells asegs m (r + 4 * qq) [C4 (Z_to_bv 64 (ksf kk qq))] /\ FB fmt_single 1 (ksf kk qq))
  /\ Forall (fun r => acc asegs m r (4 * k_sx q)) (k_rows q)
  /\ ksf (k_cy q) (k_cx q) = p_one_s
  /\ rw_cells asegs m (k_SXP q) [C4 (Z_to_bv 64 (k_sx q))]
  /\ rw_cells asegs m (k_RKP q) [C8 (Z_to_bv 64 (k_rdata q))] /\ acc asegs m (k_RKP q) 8
  /\ rw_cells asegs m (k_rdata q) [C8 (Z_to_bv 64 (k_RR q))] /\ acc asegs m (k_rdata q) 8
  /\ (forall qq, 0 <= qq < 256 -> rw_cells asegs m (k_RR q + 4 * qq) [C4 (Z_to_bv 64 (rs qq))] /\ FB fmt_single 1 (rs qq)) /\ acc asegs m (k_RR q) 1024
  /\ rs 0 = p_one_s.

(* [comment removed for export] *)
Definition bge_linet (q : bgk) (i kk : Z) : Z := k_D q + (i + kk) * k_wpls q * 4.

(* [comment removed for export] *)
Definition bge_k_exit (q : bgk) (i j c : Z) (sp gp tp s0 s1 s2 s4 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' a0' a2' a3' s3' s5' s8' t4' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (s' n' : Z),
    ms' = MS (mkR ra' sp gp tp t0' t1' (Z_to_bv 64 j) s0 s1 a0' (Z_to_bv 64 (k_RKP q)) a2' a3' (Z_to_bv 64 i) (Z_to_bv 64 (k_sy q)) (Z_to_bv 64 1) (Z_to_bv 64 3)
                  s2 s3' s4 s5' (Z_to_bv 64 (k_SXP q)) (Z_to_bv 64 (k_KELP q)) s8' (Z_to_bv 64 2147450880) (Z_to_bv 64 (k_wpls q)) (Z_to_bv 64 (k_D q))
                  (Z_to_bv 64 (k_sy q)) t4' (Z_to_bv 64 c) t6')
             F' (Z_to_bv 64 0xd1b50) fc' None m (seg_rom asegs)
    /\ fs_agree F F' /\ f15_kept F F' /\ frm0 fc' /\ acc_regs F' s' n' /\ ge_avg (k_sy q * k_sx q) true s' n'.

Lemma bge_k_loop : forall (n : nat) (q : bgk) (ksf : Z -> Z -> Z) (rs : Z -> Z) (kk i j c : Z) (cb : bool) (cbyte : byte)
    (ra sp gp tp t0 t1 s0 s1 a0 a2 a3 s2 s3 s4 s5 s8 t4 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (su nu : Z),
  Z.of_nat n = k_sy q - kk -> 0 <= kk -> (1 <= n)%nat -> bgk_ok q -> bgk_ro q ksf rs m -> mem_inv asegs m -> frm0 fc ->
  0 <= i < k_h q -> 0 <= j < k_w q -> 0 <= c < 256 ->
  rw_cells asegs m (Z.lxor (bge_linet q i (k_cy q) + j + k_cx q) 3) [CB 1 [cbyte]] -> c = bv_unsigned cbyte ->
  acc_regs F su nu -> ge_avg (kk * k_sx q) cb su nu -> (k_cy q < kk -> cb = true) ->
  evt asegs (bge_k_exit q i j c sp gp tp s0 s1 s2 s4 F m)
    (MS (mkR ra sp gp tp t0 t1 (Z_to_bv 64 j) s0 s1 a0 (Z_to_bv 64 (k_RKP q)) a2 a3 (Z_to_bv 64 i) (Z_to_bv 64 kk) (Z_to_bv 64 1) (Z_to_bv 64 3)
             s2 s3 s4 s5 (Z_to_bv 64 (k_SXP q)) (Z_to_bv 64 (k_KELP q)) s8 (Z_to_bv 64 2147450880) (Z_to_bv 64 (k_wpls q)) (Z_to_bv 64 (k_D q))
             (Z_to_bv 64 (k_sy q)) t4 (Z_to_bv 64 c) t6)
        F (Z_to_bv 64 0xd1940) fc None m (seg_rom asegs)).
Proof.
