(* [comment removed for export] *)
(* [comment removed for export] *)
Record bgj : Type := mk_bgj { j_rf : Z; j_CYP : Z; j_CXP : Z; j_SYP : Z; j_WP : Z; j_HP : Z; j_DD : Z; j_ND : Z; j_wpld : Z }.
Definition bgj_ok (q : bgk) (r : bgj) : Prop :=
  arange (j_rf r) 128 /\ j_rf r mod 8 = 0
  /\ arange (j_DD r) (j_ND r) /\ j_DD r mod 4 = 0 /\ j_ND r = 4 * (j_wpld r * k_h q) /\ 0 < j_wpld r /\ k_w q <= 4 * j_wpld r /\ j_wpld r * k_h q <= 2^26
  /\ (j_DD r + j_ND r <= j_rf r \/ j_rf r + 128 <= j_DD r).

(* [comment removed for export] *)
Definition bge_lined (r : bgj) (i : Z) : Z := j_DD r + i * j_wpld r * 4.

(* [comment removed for export] *)
Definition bgf_ro (q : bgk) (r : bgj) (m : mem) : Prop :=
  rw_cells asegs m (j_rf r + 40) [C8 (Z_to_bv 64 (j_wpld r)); C8 (Z_to_bv 64 (j_DD r)); C8 (Z_to_bv 64 (j_CYP r)); C8 (Z_to_bv 64 (j_CXP r)); C8 (Z_to_bv 64 1)]
  /\ rw_cells asegs m (j_rf r + 88) [C8 (Z_to_bv 64 (j_HP r))]
  /\ rw_cells asegs m (j_rf r + 104) [C8 (Z_to_bv 64 (j_SYP r)); C8 (Z_to_bv 64 (j_WP r))]
  /\ rw_cells asegs m (j_CYP r) [C4 (Z_to_bv 64 (k_cy q))] /\ rw_cells asegs m (j_CXP r) [C4 (Z_to_bv 64 (k_cx q))]
  /\ rw_cells asegs m (j_SYP r) [C4 (Z_to_bv 64 (k_sy q))] /\ rw_cells asegs m (j_WP r) [C4 (Z_to_bv 64 (k_w q))]
  /\ rw_cells asegs m (j_HP r) [C4 (Z_to_bv 64 (k_h q))].

(* [comment removed for export] *)
Definition bge_Wj (r : bgj) : list (Z * Z) := [(j_DD r, j_DD r + j_ND r); (j_rf r + 120, j_rf r + 128)].

(* [comment removed for export] *)
Definition bge_j_exit (q : bgk) (r : bgj) (i : Z) (sp gp tp s0 s2 s4 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' a0' a2' a3' a5' s3' s5' s8' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (j_rf r)) a0' (Z_to_bv 64 (k_RKP q)) a2' a3' (Z_to_bv 64 i) a5' (Z_to_bv 64 1) (Z_to_bv 64 3)
                  s2 s3' s4 s5' (Z_to_bv 64 (k_SXP q)) (Z_to_bv 64 (k_KELP q)) s8' (Z_to_bv 64 2147450880) (Z_to_bv 64 (k_wpls q)) (Z_to_bv 64 (k_D q))
                  t3' t4' t5' t6')
             F' (Z_to_bv 64 0xd180c) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ f15_kept F F' /\ frm0 fc' /\ munch (bge_Wj r) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ rw_cells asegs m' (j_rf r + 120) [C8 (Z_to_bv 64 (k_w q))].

(* [comment removed for export] *)
Lemma bge_j_loop : forall (n : nat) (q : bgk) (r : bgj) (ksf : Z -> Z -> Z) (rs : Z -> Z) (i j : Z)
    (ra sp gp tp t0 t1 s0 a0 a2 a3 a5 s2 s3 s4 s5 s8 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = k_w q - j -> 0 <= j -> (1 <= n)%nat -> 0 <= i < k_h q -> bgk_ok q -> bgj_ok q r -> frm0 fc ->
  reg_get F (Z_to_bv 5 15) = nan_box (Z_to_bv 32 0) ->
  (forall m', munch (bge_Wj r) m m' -> wmono asegs m m' ->
     bgk_ro q ksf rs m' /\ bgf_ro q r m' /\ rw_cells asegs m' (j_rf r + 96) [C8 (Z_to_bv 64 (bge_lined r i))]) ->
  rw_cells asegs m (j_rf r + 120) [C8 (Z_to_bv 64 j)] ->
  wr_at asegs m (j_DD r) (j_ND r) -> acc asegs m (j_DD r) (j_ND r) -> mem_inv asegs m ->
  evt asegs (bge_j_exit q r i sp gp tp s0 s2 s4 F m)
    (MS (mkR ra sp gp tp t0 t1 (Z_to_bv 64 j) s0 (Z_to_bv 64 (j_rf r)) a0 (Z_to_bv 64 (k_RKP q)) a2 a3 (Z_to_bv 64 i) a5 (Z_to_bv 64 1) (Z_to_bv 64 3)
             s2 s3 s4 s5 (Z_to_bv 64 (k_SXP q)) (Z_to_bv 64 (k_KELP q)) s8 (Z_to_bv 64 2147450880) (Z_to_bv 64 (k_wpls q)) (Z_to_bv 64 (k_D q))
             t3 t4 t5 t6)
