(* [comment removed for export] *)
Definition bge_Wi (r : bgj) : list (Z * Z) := [(j_DD r, j_DD r + j_ND r); (j_rf r + 96, j_rf r + 104); (j_rf r + 120, j_rf r + 128)].

(* [comment removed for export] *)
Definition bge_i_exit (q : bgk) (r : bgj) (sp gp tp s0 s2 s4 : word) (F : bvmap 5 word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' a0' a2' a3' a4' a5' s3' s5' s8' t3' t4' t5' t6' : word) (F' : bvmap 5 word) (fc' : bv 32) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0 (Z_to_bv 64 (j_rf r)) a0' (Z_to_bv 64 (k_RKP q)) a2' a3' a4' a5' (Z_to_bv 64 1) (Z_to_bv 64 3)
                  s2 s3' s4 s5' (Z_to_bv 64 (k_SXP q)) (Z_to_bv 64 (k_KELP q)) s8' (Z_to_bv 64 2147450880) (Z_to_bv 64 (k_wpls q)) (Z_to_bv 64 (k_D q))
                  t3' t4' t5' t6')
             F' (Z_to_bv 64 0xd1ddc) fc' None m' (seg_rom asegs)
    /\ fs_agree F F' /\ frm0 fc' /\ munch (bge_Wi r) m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma bge_i_loop : forall (n : nat) (q : bgk) (r : bgj) (ksf : Z -> Z -> Z) (rs : Z -> Z) (i : Z)
    (ra sp gp tp t0 t1 t2 s0 a0 a2 a3 a5 s2 s3 s4 s5 s8 t3 t4 t5 t6 x96 x120 : word) (F : bvmap 5 word) (fc : bv 32) (m : mem),
  Z.of_nat n = k_h q - i -> 0 <= i -> (1 <= n)%nat -> bgk_ok q -> bgj_ok q r -> frm0 fc ->
  reg_get F (Z_to_bv 5 15) = nan_box (Z_to_bv 32 0) ->
  (forall m', munch (bge_Wi r) m m' -> wmono asegs m m' -> bgk_ro q ksf rs m' /\ bgf_ro q r m') ->
  rw_cells asegs m (j_rf r + 96) [C8 x96] -> rw_cells asegs m (j_rf r + 120) [C8 x120] ->
  wr_at asegs m (j_DD r) (j_ND r) -> acc asegs m (j_DD r) (j_ND r) -> mem_inv asegs m ->
  evt asegs (bge_i_exit q r sp gp tp s0 s2 s4 F m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 (Z_to_bv 64 (j_rf r)) a0 (Z_to_bv 64 (k_RKP q)) a2 a3 (Z_to_bv 64 i) a5 (Z_to_bv 64 1) (Z_to_bv 64 3)
             s2 s3 s4 s5 (Z_to_bv 64 (k_SXP q)) (Z_to_bv 64 (k_KELP q)) s8 (Z_to_bv 64 2147450880) (Z_to_bv 64 (k_wpls q)) (Z_to_bv 64 (k_D q))
             t3 t4 t5 t6)
